#include <iostream>
using namespace std;

int binarySearch(int arr[], int n, int target) {
    int low = 0, high = n - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2; // تجنب overflow
        if (arr[mid] == target) return mid;
        if (arr[mid] < target) low = mid + 1;
        else high = mid - 1;
    }
    return -1;
}

int main() {
    int arr[] = {2, 5, 8, 12, 16, 23, 38, 56, 72, 91};
    int n = sizeof(arr) / sizeof(arr[0]);
    int targets[] = {23, 5, 100};
    for (int t : targets) {
        int idx = binarySearch(arr, n, t);
        if (idx != -1) cout << "Found " << t << " at index " << idx << endl;
        else cout << t << " not found" << endl;
    }
    return 0;
}

