struct Node {
    int data;
    Node* left;
    Node* right;
};

void insert(Node*& root, int val) {
    if (!root) {
        root = new Node{val, nullptr, nullptr};
        return;
    }
    if (val < root->data) insert(root->left, val);
    else insert(root->right, val);
}

void inorder(Node* root) {
    if (!root) return;
    inorder(root->left);
    cout << root->data << " ";
    inorder(root->right);
}

