#include <iostream>

int main() {
    const int N = 2;
    int A[N][N] = {{1, 2}, {3, 4}};
    int B[N][N] = {{5, 6}, {7, 8}};
    int C[N][N] = {};

    // ضرب المصفوفات: C[i][j] = sum_k A[i][k]*B[k][j]
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            for (int k = 0; k < N; ++k)
                C[i][j] += A[i][k] * B[k][j];

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j)
            std::cout << C[i][j] << " ";
        std::cout << std::endl;
    }
    return 0;
}

