long long fib(int n) {
    static long long memo[100] = {0, 1};
    // لماذا static؟ لأنها تحفظ القيم بين الاستدعاءات
    if (n == 0) return 0;
    if (n == 1) return 1;
    if (memo[n] != 0) return memo[n];
    return memo[n] = fib(n - 1) + fib(n - 2);
}
