            for (int j = i * i; j <= LIMIT; j += i)
                isPrime[j] = false;
        }
    }

    for (int i = 2; i <= LIMIT; ++i)
        if (isPrime[i])
            std::cout << i << " ";
    std::cout << std::endl;
