    int start = 0, end = s.length() - 1;
    // نتخطى المسافات من البداية والنهاية
    while (start <= end && s[start] == ' ') start++;
    while (end >= start && s[end] == ' ') end--;
    std::string trimmed = s.substr(start, end - start + 1);
    std::cout << trimmed << std::endl;
    return 0;
}

