#include <iostream>
int main() {
    int count = 3;
    while (count > 0) {
        std::cout << count << "\n";
        --count;
    }
    std::cout << "Liftoff!\n";
    return 0;
}

#include <iostream>
#include <string>

int main() {
    std::string s = "C++ programming is fun";
    int count = 0;
    bool inWord = false;
    // نعد كل انتقال من مسافة إلى حرف كبداية كلمة
    for (char c : s) {
        if (c == ' ') {
            inWord = false;
        } else if (!inWord) {
            inWord = true;
            count++;
        }
    }
    std::cout << count << std::endl;
    return 0;
}

