#include <iostream>
class Base {
public:
    virtual void show() { std::cout << "Base"; } // تعدد الأشكال
};
class Derived : public Base {
public:
    void show() override { std::cout << "Derived"; }
};
int main() {
    Base* b = new Derived();
    b->show();
    delete b;
    return 0;
}

#include <iostream>
void byRef(int& r) { r += 1; } // تعديل مباشر
void byPtr(int* p) { *p += 2; } // تعديل عبر مؤشر
int main() {
    int x = 0;
    byRef(x);
    byPtr(&x);
    std::cout << x;
    return 0;
}

#include <iostream>
template <typename T>
T max(T a, T b) { return (a > b) ? a : b; } // يعمل مع أي نوع
int main() {
    std::cout << max(3, 7) << " " << max(2.5, 1.8);
    return 0;
}

