#include <iostream>
class Point {
public:
    int x, y;
    Point(int a, int b) : x(a), y(b) {}
    Point operator+(const Point& p) { return Point(x + p.x, y + p.y); } // جمع نقطتين
};
int main() {
    Point a(1, 2), b(3, 4);
    Point c = a + b;
    std::cout << c.x << " " << c.y;
    return 0;
}
